def split(line):
    out = []
    cur = None  # None means no word started yet
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if ch.isspace():
            if cur is not None:
                out.append(cur)
                cur = None
            i += 1
        elif ch == "'":
            if cur is None:
                cur = ''
            i += 1  # opening single quote
            closed = False
            while i < n:
                if line[i] == "'":
                    closed = True
                    i += 1
                    break
                cur += line[i]
                i += 1
            if not closed:
                raise ValueError("unterminated single quote")
        elif ch == '"':
            if cur is None:
                cur = ''
            i += 1  # opening double quote
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    closed = True
                    i += 1
                    break
                if c == '\\' and i + 1 < n and line[i + 1] in ('"', '\\'):
                    cur += line[i + 1]
                    i += 2
                else:
                    cur += c
                    i += 1
            if not closed:
                raise ValueError("unterminated double quote")
        elif ch == '\\':
            if cur is None:
                cur = ''
            if i + 1 < n:
                cur += line[i + 1]
                i += 2
            else:
                # backslash at very end of line is kept as a character
                cur += '\\'
                i += 1
        else:
            if cur is None:
                cur = ''
            cur += ch
            i += 1
    if cur is not None:
        out.append(cur)
    return out

